import type { AttributeInputType, AttributeLevel, I18nText } from "@fluxkit/core";

// Pure data shapes. Entities reference each other by stable code or slug, never by id: ids are generated by the
// database, so the same seed produces different ids on every database.

export interface SeedValue {
  code: string;
  label: I18nText;
}

export interface SeedAttribute {
  code: string;
  name: I18nText;
  inputType: AttributeInputType;
  /** Text attributes are localized unless this says otherwise. */
  isLocalized?: boolean;
  unit?: string;
  validation?: Readonly<Record<string, unknown>>;
  isFilterable?: boolean;
  isSortable?: boolean;
  isInternal?: boolean;
  /** Only for `select` and `multiselect`. */
  options?: readonly SeedValue[];
}

export interface SeedOption {
  code: string;
  name: I18nText;
  values: readonly SeedValue[];
}

export interface SeedProductTypeAttribute {
  attributeCode: string;
  level: AttributeLevel;
  isRequired?: boolean;
}

export interface SeedProductType {
  code: string;
  name: I18nText;
  requiresShipping: boolean;
  attributes: readonly SeedProductTypeAttribute[];
  /** Option codes, in display order. Empty for a type whose products have a single default variant. */
  optionCodes: readonly string[];
}

export interface SeedBrand {
  slug: string;
  name: I18nText;
}

export interface SeedCategory {
  slug: string;
  name: I18nText;
  /** One level of children: the demo tree is two levels deep. */
  children?: readonly SeedCategory[];
}

export interface SeedProductOption {
  optionCode: string;
  valueCodes: readonly string[];
}

export interface SeedMedia {
  /** Always `https://example.com/placeholder/<name>.jpg`. */
  url: string;
  alt: I18nText;
  /** Ties the image to one option value (for example one color); omit for a gallery image. */
  optionValue?: { optionCode: string; valueCode: string };
}

export interface SeedProduct {
  slug: string;
  title: I18nText;
  description: I18nText;
  productTypeCode: string;
  brandSlug: string;
  /** The first category is the primary one. */
  categorySlugs: readonly string[];
  /** Product-level attribute values keyed by attribute code, in the storage format of ADR 0006 section 4. */
  attributes: Readonly<Record<string, unknown>>;
  options: readonly SeedProductOption[];
  media: readonly SeedMedia[];
}

export interface CatalogSeed {
  attributes: readonly SeedAttribute[];
  options: readonly SeedOption[];
  productTypes: readonly SeedProductType[];
  brands: readonly SeedBrand[];
  categories: readonly SeedCategory[];
  products: readonly SeedProduct[];
}
